/// The receipt is versioned: a change to its shape without a `SCHEMA_VERSION`
/// bump is a silent break for receipts written by an earlier release. The
/// receipt is at version 2 and its run envelope at version 3 (no run kind, no profile).
#[test]
fn durable_release_wire_shapes_match_their_schema_version() {
    let receipt = run_schema("release-receipt");
    let (req, props) = required_and_props(&receipt);
    let expected = set(&["schemaVersion", "intentDigest", "envelope", "outcomes", "observations"]);
    assert_eq!(req, expected);
    assert_eq!(props, expected);

    let (req, props) = required_and_props(&receipt["definitions"]["ReleaseRunEnvelopeV1"]);
    let mut expected = set(&[
        "schemaVersion",
        "orchestrationRevision",
        "releaseSourceRevision",
        "intentDigest",
    ]);
    assert_eq!(req, expected);
    expected.insert("artifactManifestDigest".to_owned());
    assert_eq!(props, expected);
}

/// The operation role is the durable DAG's vocabulary: a receipt names every
/// operation by it. `forgePublish` is the role that makes publication the last
/// forge step, after every `artifactUpload`.
#[test]
fn release_operation_roles_carry_exactly_their_declared_variants() {
    let receipt = run_schema("release-receipt");
    let variants: BTreeSet<String> = receipt["definitions"]["ReleaseOperationRole"]["oneOf"]
        .as_array()
        .unwrap()
        .iter()
        .map(|variant| {
            variant["properties"]["kind"]["enum"][0]
                .as_str()
                .expect("every role variant names itself")
                .to_owned()
        })
        .collect();
    assert_eq!(
        variants,
        set(&[
            "registryPublish",
            "tag",
            "forgeRelease",
            "artifactUpload",
            "forgePublish",
            "platformPublish",
        ])
    );
}

/// Both observation enums are closed and persisted in receipts, so a
/// reader from an earlier release must be able to name every value it can meet.
/// Adding one is intentional and belongs here; losing one silently is not.
#[test]
fn provider_observation_enums_carry_exactly_their_declared_variants() {
    let receipt = run_schema("release-receipt");
    let variants = |name: &str| -> BTreeSet<String> {
        receipt["definitions"][name]["oneOf"]
            .as_array()
            .unwrap()
            .iter()
            .map(|variant| {
                variant["enum"]
                    .get(0)
                    .or_else(|| variant["properties"]["kind"]["enum"].get(0))
                    .and_then(serde_json::Value::as_str)
                    .expect("every variant names itself")
                    .to_owned()
            })
            .collect()
    };

    assert_eq!(
        variants("ProviderConflictReason"),
        set(&[
            "localTagDiffers",
            "remoteTagTargetDiffers",
            "unannotatedTag",
            "forgeReleaseDiffers",
            "forgeReleasePrereleaseDiffers",
            "artifactAssetDiffers",
            "duplicateArtifactAsset",
            "registryVersionYanked",
        ])
    );
    assert_eq!(
        variants("ProviderIndeterminateCause"),
        set(&[
            "unsupportedProvider",
            "providerStatus",
            "commandFailed",
            "malformedResponse",
            "timeout",
            "registryVersionUnverified",
            "artifactManifestUnavailable",
        ])
    );
}
use std::process::ExitCode;

use callisto_model::format::{Changeset, PreState};
use callisto_model::{InitReport, MatrixReport, ReleaseReceiptV1, SnapshotReport, StatusReport, VersionReport};
use schemars::schema_for;

use crate::cli::{GlobalArgs, SchemaArgs, SchemaReportType};
use crate::error::CliError;
use crate::output::write_stdout;

pub fn handle(args: SchemaArgs, _global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let schema = match args.target_type.unwrap_or_default() {
        SchemaReportType::Status => schema_for!(StatusReport),
        SchemaReportType::Version => schema_for!(VersionReport),
        SchemaReportType::Snapshot => schema_for!(SnapshotReport),
        SchemaReportType::Init => schema_for!(InitReport),
        SchemaReportType::Changeset => schema_for!(Changeset),
        SchemaReportType::PreState => schema_for!(PreState),
        SchemaReportType::Matrix => schema_for!(MatrixReport),
        SchemaReportType::ReleaseReceipt => schema_for!(ReleaseReceiptV1),
    };

    // A `schemars::Schema` is a plain JSON tree of strings, numbers, and nested maps;
    // it always serializes.
    let json = serde_json::to_string_pretty(&schema).expect("schema serializes");
    write_stdout(format!("{json}\n").as_bytes())?;
    Ok(ExitCode::SUCCESS)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn global() -> GlobalArgs {
        GlobalArgs {
            format: crate::cli::OutputFormat::Text,
            cwd: std::path::PathBuf::from("."),
            dry_run: false,
        }
    }

    /// Every registry entry actually produces a schema; an unknown `--type`
    /// value is rejected earlier, at clap parse time (see `cli.rs`'s
    /// `schema_type_rejects_unknown_value_as_a_usage_error`), so this
    /// handler-level test only needs to cover the exhaustive match's arms.
    #[test]
    fn handle_succeeds_for_every_registered_type() {
        for target_type in [
            SchemaReportType::Status,
            SchemaReportType::Version,
            SchemaReportType::Snapshot,
            SchemaReportType::Init,
            SchemaReportType::Changeset,
            SchemaReportType::PreState,
            SchemaReportType::Matrix,
            SchemaReportType::ReleaseReceipt,
        ] {
            let result = handle(
                SchemaArgs {
                    target_type: Some(target_type),
                },
                &global(),
            );
            assert!(result.is_ok(), "target_type={target_type:?}");
        }
    }
}
