mod tests {
    use callisto_model::{Diagnostic, Report};
    use serde::Deserialize;

    use super::*;

    #[derive(Serialize, Deserialize)]
    struct FakeReport {
        value: u32,
    }

    impl callisto_model::Report for FakeReport {
