    pub fn apply(
        &mut self,
        id: &ReleaseOperationId,
        event: &OperationEvent,
    ) -> Result<OperationState, ReleaseStateError> {
        let state = self
            .operations
            .get_mut(id)
            .ok_or_else(|| ReleaseStateError::UnknownOperation {
                id: Box::new(id.clone()),
            })?;
        let next = crate::release_transition::transition(*state, event).map_err(|source| {
