#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum ReleaseTrigger {
    #[default]
    Changeset,
    Auto,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn maps_ecosystem_prefixes() {
        assert_eq!(Ecosystem::from_prefix("cargo"), Some(Ecosystem::Cargo));
        assert_eq!(Ecosystem::from_prefix("npm"), Some(Ecosystem::Npm));
        assert_eq!(Ecosystem::Cargo.prefix(), "cargo");
    }

    #[test]
    fn identifies_implemented_ecosystems() {
        assert!(Ecosystem::Cargo.is_implemented());
        assert!(Ecosystem::Npm.is_implemented());
        assert!(Ecosystem::Pypi.is_implemented());
    }

    #[test]
    fn canonical_ecosystems_each_have_a_canonical_manifest_format() {
        assert_eq!(Ecosystem::CANONICAL.len(), 3);
        assert_eq!(
            Ecosystem::Cargo.canonical_manifest_format(),
            Some(ManifestFormat::CargoToml)
        );
        assert_eq!(
            Ecosystem::Npm.canonical_manifest_format(),
            Some(ManifestFormat::PackageJson)
        );
        assert_eq!(
            Ecosystem::Pypi.canonical_manifest_format(),
            Some(ManifestFormat::PyprojectToml)
        );
    }

    #[test]
    fn non_canonical_ecosystems_have_no_canonical_manifest_format() {
        assert_eq!(Ecosystem::Go.canonical_manifest_format(), None);
        assert_eq!(Ecosystem::Maven.canonical_manifest_format(), None);
        assert_eq!(Ecosystem::NuGet.canonical_manifest_format(), None);
        assert_eq!(Ecosystem::Deno.canonical_manifest_format(), None);
        assert_eq!(Ecosystem::Jsr.canonical_manifest_format(), None);
    }

    #[test]
    fn normalize_pypi_package_name_treats_hyphen_underscore_dot_as_equivalent() {
        assert_eq!(normalize_pypi_package_name("my-package"), "my_package");
        assert_eq!(normalize_pypi_package_name("my_package"), "my_package");
        assert_eq!(normalize_pypi_package_name("my.package"), "my_package");
        assert_eq!(normalize_pypi_package_name("My--Package"), "my_package");
        assert_eq!(normalize_pypi_package_name("MY.PACKAGE"), "my_package");
        assert_eq!(normalize_pypi_project_name("My--Package"), "my-package");
        assert_eq!(normalize_pypi_project_name("MY.PACKAGE"), "my-package");
    }

    #[test]
    fn normalize_pypi_package_name_collapses_mixed_runs() {
        assert_eq!(normalize_pypi_package_name("foo-.-bar"), "foo_bar");
        assert_eq!(normalize_pypi_package_name("foo___bar"), "foo_bar");
    }

    #[test]
    fn publish_target_registry_override_extracts_payload_field() {
        assert_eq!(PublishTarget::CratesIo.registry_override(), None);
        assert_eq!(
            PublishTarget::Npm {
                registry: Some("https://npm.example.com".to_string()),
                access: None
            }
            .registry_override(),
            Some("https://npm.example.com")
        );
        assert_eq!(
            PublishTarget::Npm {
                registry: None,
                access: None
            }
            .registry_override(),
            None
        );
        assert_eq!(
            PublishTarget::Pypi {
                index: Some("https://pypi.example.com".to_string())
            }
            .registry_override(),
            Some("https://pypi.example.com")
        );
        assert_eq!(
            PublishTarget::NuGet {
                source: Some("https://nuget.example.com".to_string())
            }
            .registry_override(),
            Some("https://nuget.example.com")
        );
        assert_eq!(PublishTarget::GitHubRelease.registry_override(), None);
        assert_eq!(PublishTarget::None.registry_override(), None);
    }

    #[test]
    fn publish_target_is_implemented_matches_dispatchable_variants() {
        assert!(PublishTarget::CratesIo.is_implemented());
        assert!(PublishTarget::Npm {
            registry: None,
            access: None
        }
        .is_implemented());
        assert!(PublishTarget::Pypi { index: None }.is_implemented());
        assert!(!PublishTarget::NuGet { source: None }.is_implemented());
        assert!(PublishTarget::GitHubRelease.is_implemented());
        // `None` is vacuously "implemented" -- there is nothing to dispatch,
        // so it must never trip a `PublishTargetNotImplemented` diagnostic.
        assert!(PublishTarget::None.is_implemented());
    }
}

