    ReleaseInclusionReason, ReleaseInputSnapshotV1, ReleaseIntentV1, ReleaseOperation, ReleasePackageId,
    ReleasePackageInputV1, ReleasePrDecisionV2, ReleasePrPullRequestV2, ReleasePrSnapshotV2, ReleaseReceiptV1,
